modules.example:
const { data } = await sdk.auth.login({ email, password })
  if (data?.two_factor_required) {
    await sdk.auth.twoFactor.verify({ token: data.two_factor_token!, code: '123456' })
  }

sdk.client.setGuestId(localStorage.getItem('guest') ?? crypto.randomUUID())
  await sdk.cart.add({ record_id: 12, quantity: 2 })
  const { data } = await sdk.cart.get()

modules.body:
Bir tip tanımlarsınız (örn. `blog`, alanları: başlık, görsel, içerik), sonra
`sdk.records` ile o tipte kayıt açarsınız. Şema değişiklikleri sürümlenir;
eski kayıtlar hangi sürümle yazıldıysa onu taşır.

modules.example:
await sdk.contentTypes.create({
    code: 'blog',
    label: 'Blog Yazısı',
    kind: 'content',
    fields: [
      { code: 'baslik', label: 'Başlık', type: 'text', required: true },
      { code: 'icerik', label: 'İçerik', type: 'richtext' },
    ],
  })

await sdk.menus.update('ana-menu', {
    items: [
      { label: 'Anasayfa', url: '/' },
      { label: 'Blog', type: 'blog', children: [{ label: 'Tümü', url: '/blog' }] },
    ],
  })
